# VENDORED COPY -- generated by tools/build_addon.py from core/verdict.py
# Edit core/verdict.py, not this file.
#!/usr/bin/env python3
r"""
verdict.py -- a safety answer that can say "I could not look", and cannot be
mistaken for "nothing to worry about".

WHY THIS IS ONE TYPE AND NOT A CONVENTION
-----------------------------------------
Five places in this tree, sharing no code, had the same defect: **a safety
predicate whose error answer and whose permissive answer are the same value.**

  * `tools/verdictcheck.py`  an unreadable receipt -> empty `gate_union`
                             -> `APPLIES`, waiving the whole merge
  * `tools/verdictcheck.py`  a non-`.py` artefact cannot enter the uncovered
                             list on any input -> the ledger reads "covered"
  * `tools/selftests.py`     the call-graph walk goes dark on an unresolvable
                             callee -> `[]` reads "headless, safe to run
                             against a live client"
  * `tools/selftests.py`     a method name bound twice -> one silently
                             discarded, the other class's method inspected
  * `client/redact.py`       (FIXED at bc1f261) `except: return []`, where an
                             empty range list is the *not secret* answer

The caller cannot distinguish *"I looked and found nothing"* from *"I could not
look."* Both read as safe. See `docs/empty_is_the_permissive_answer.md`.

**The fix shape was already in this tree, twice, in two different spellings:**

  * `clientlock.running_clients()` **raises** on all 8 failure paths, because
    "I could not tell" must not read as "the box is empty";
  * `redact._secret_lookup()` returns `(ranges, errored)` and every caller
    treats `errored=True` as *the whole frame is secret*.

Two spellings of one idea is precisely how `core/safepath.py` was born -- the
same bug fixed three times in three styles, one of them subtly wrong. So this is
the third spelling and it is meant to be the last one.

WHY THE VIOLATION CANNOT BE FOUND BY A SCAN
-------------------------------------------
Measured, before this type was proposed: a scan for *"an `except` handler that
returns an empty or falsy value"* fires **210 times across 372 files** in this
tree, almost all of it correct code -- a cache miss returning `None` is not a
safety inversion. A gate at that fire rate is worse than no gate, because the
next person widens it until it is inert.

**The defect is not in the definition; it is in the contract between definition
and caller.** `return []` is only wrong when a caller reads `[]` as *permit*, and
"is this value consumed as a safety verdict" is not recoverable from disk.

So the violation is not made *detectable*. It is made **unrepresentable**:

  * `bool(verdict)` **raises**, always, in every state. There is no silent
    degradation to a two-state boolean, and `if not verdict:` is a crash rather
    than a permit.
  * A `Verdict` is equal to no empty collection, no `None`, no `False` and no
    `0`, so a caller comparing against the old sentinel never matches.
  * `permits()` has **no default** for `on_unknown`. You cannot extract a bool
    without stating, at the call site, what "I could not look" means there.

THE POLICY IS THE CALLER'S, AND IT IS ALWAYS WRITTEN DOWN
---------------------------------------------------------
For every guard in this project the correct policy is fail-safe -- treat UNKNOWN
as REFUSE -- but that is a decision belonging to the call site, not to this
module, and `redact._secret_lookup` is the reason: it keeps `spec is None` as
*genuinely* not-secret, because a blunt fail-closed would over-redact every
unknown frame and destroy the capture. Three states, and the third is not the
union of the other two. A type that hard-coded fail-closed would have made that
call site worse.

NO GATE SHIPS WITH THIS, DELIBERATELY
-------------------------------------
The obvious companion is a gate requiring every `except` inside a
`Verdict`-returning function to return `UNKNOWN`. **It is not here, because
nothing returns a `Verdict` yet** -- it would sweep an empty set and pass, which
is this project's third gate failure mode: a check that cannot fire on the
available material is not a check. The gate lands with the first consumer, and
its first positive control is that consumer.
"""
from __future__ import annotations

__all__ = ["Verdict", "UnknownVerdict", "PERMIT", "REFUSE"]

#: `on_unknown` sentinels. Deliberately not `True`/`False`: a caller writing
#: `permits(on_unknown=False)` is expressing a boolean, not a policy, and the
#: whole point of this type is that the two are different.
PERMIT = "permit"
REFUSE = "refuse"

_STATES = ("permit", "refuse", "unknown")


class UnknownVerdict(RuntimeError):
    """Raised when an UNKNOWN verdict is forced to a decision that was never
    made. Carries what could not be seen, so the message names the gap."""

    def __init__(self, verdict: "Verdict"):
        self.verdict = verdict
        unseen = ", ".join(verdict.unseen[:6]) or "(nothing recorded)"
        more = f" (+{len(verdict.unseen) - 6} more)" if len(verdict.unseen) > 6 else ""
        super().__init__(
            f"verdict is UNKNOWN and no policy was given for it. "
            f"Could not examine: {unseen}{more}. "
            f"Call .permits(on_unknown=REFUSE) to fail safe -- which is the "
            f"right answer for every guard in this project -- or "
            f"on_unknown=PERMIT and say in a comment why not looking is fine "
            f"here.")


class Verdict:
    r"""A three-state safety answer: PERMIT, REFUSE, or UNKNOWN.

    Construct through the classmethods, never directly:

        Verdict.permit("no credential field in this spec")
        Verdict.refuse("spec 1051 carries a password at offset 4")
        Verdict.unknown(["callee `wrap()` is in another module"])

    UNKNOWN is not an error and not a refusal -- it is the honest answer when
    the instrument had no power over the question. It **carries what it could
    not see**, because a bare "unknown" is only marginally better than a wrong
    answer: the caller cannot judge the gap, and the next reader cannot narrow
    it.
    """

    __slots__ = ("_state", "_detail", "_unseen")

    def __init__(self, state: str, detail: str = "", unseen=()):
        if state not in _STATES:
            raise ValueError(f"state must be one of {_STATES}, got {state!r}")
        if state == "unknown" and not unseen:
            # An UNKNOWN that cannot say what it missed is the two-state answer
            # wearing a third name, and it is exactly what this type exists to
            # prevent. Refuse it at construction.
            raise ValueError(
                "Verdict.unknown() requires a non-empty `unseen` -- an UNKNOWN "
                "that cannot name what it could not examine is a bare negative "
                "with a nicer label.")
        self._state = state
        self._detail = detail
        self._unseen = tuple(unseen)

    # -- construction ------------------------------------------------------

    @classmethod
    def permit(cls, detail: str = "") -> "Verdict":
        """I looked, and there is nothing here to refuse."""
        return cls("permit", detail)

    @classmethod
    def refuse(cls, detail: str = "") -> "Verdict":
        """I looked, and the answer is yes -- refuse."""
        return cls("refuse", detail)

    @classmethod
    def unknown(cls, unseen, detail: str = "") -> "Verdict":
        """I could not look. `unseen` names what was out of the instrument's
        power -- a dark callee, an unparsed file, an artefact of a type this
        check has no domain over."""
        if isinstance(unseen, str):
            unseen = (unseen,)
        return cls("unknown", detail, unseen)

    # -- inspection --------------------------------------------------------

    @property
    def state(self) -> str:
        return self._state

    @property
    def detail(self) -> str:
        return self._detail

    @property
    def unseen(self) -> tuple:
        """What the instrument could not examine. Empty unless UNKNOWN."""
        return self._unseen

    @property
    def is_permit(self) -> bool:
        return self._state == "permit"

    @property
    def is_refuse(self) -> bool:
        return self._state == "refuse"

    @property
    def is_unknown(self) -> bool:
        return self._state == "unknown"

    # -- the decision, which cannot be taken by accident -------------------

    def permits(self, *, on_unknown: str) -> bool:
        """Collapse to a bool, having stated what UNKNOWN means here.

        `on_unknown` is keyword-only and has **no default**: a call site that
        has not decided cannot compile away its indecision. For every guard in
        this project the answer is `REFUSE`.
        """
        if on_unknown not in (PERMIT, REFUSE):
            raise ValueError(
                f"on_unknown must be verdict.PERMIT or verdict.REFUSE, got "
                f"{on_unknown!r}")
        if self._state == "permit":
            return True
        if self._state == "refuse":
            return False
        return on_unknown == PERMIT

    def require_known(self) -> "Verdict":
        """Return self, or raise if UNKNOWN. For call sites where proceeding on
        an unexamined answer is never acceptable and a policy would be a lie."""
        if self._state == "unknown":
            raise UnknownVerdict(self)
        return self

    # -- the anti-degradation guarantees -----------------------------------

    def __bool__(self):
        raise TypeError(
            f"a Verdict has three states and bool() has two -- this is the "
            f"conversion that made `[]` mean 'nothing to worry about' in five "
            f"places in this tree. Use .is_permit / .is_refuse / .is_unknown, "
            f"or .permits(on_unknown=REFUSE). (this verdict: {self._state})")

    def __eq__(self, other):
        # Deliberately NOT equal to (), [], {}, None, False, 0 -- a call site
        # still comparing against the old empty-means-permissive sentinel must
        # not quietly match.
        if not isinstance(other, Verdict):
            return NotImplemented
        return (self._state == other._state
                and self._unseen == other._unseen)

    def __hash__(self):
        return hash((self._state, self._unseen))

    def __repr__(self):
        if self._state == "unknown":
            return (f"Verdict.unknown({list(self._unseen)!r}, "
                    f"detail={self._detail!r})")
        return f"Verdict.{self._state}({self._detail!r})"


def _selftest() -> int:
    """Headless. No I/O, no process, no fixture -- classify as RUN."""
    failures = []

    def check(name, cond):
        if not cond:
            failures.append(name)

    p, r = Verdict.permit("clear"), Verdict.refuse("found one")
    u = Verdict.unknown(["callee wrap() is in another module"])

    for v in (p, r, u):
        try:
            bool(v)
            failures.append(f"bool({v.state}) did not raise")
        except TypeError:
            pass

    for empty in ((), [], {}, None, False, 0, ""):
        check(f"unknown == {empty!r}", not (u == empty))

    check("permit permits", p.permits(on_unknown=REFUSE) is True)
    check("refuse refuses", r.permits(on_unknown=REFUSE) is False)
    check("unknown fails safe", u.permits(on_unknown=REFUSE) is False)
    check("unknown can permit", u.permits(on_unknown=PERMIT) is True)

    try:
        u.permits()                                    # type: ignore[call-arg]
        failures.append("permits() accepted no policy")
    except TypeError:
        pass

    try:
        Verdict.unknown([])
        failures.append("unknown([]) was accepted")
    except ValueError:
        pass

    try:
        u.require_known()
        failures.append("require_known did not raise on unknown")
    except UnknownVerdict:
        pass

    check("unseen survives", u.unseen and "wrap()" in u.unseen[0])

    if failures:
        for f in failures:
            print(f"  FAIL {f}")
        print(f"[verdict] VERDICT: FAILED -- {len(failures)} of the guarantees")
        return 1
    print("[verdict] VERDICT: PASSED -- three states, bool() refused, "
          "no empty-sentinel equality, policy mandatory")
    return 0


if __name__ == "__main__":
    raise SystemExit(_selftest())
